INSERT OR IGNORE INTO calendars (calendar_id, user_id, name, color, timezone, is_primary, created_at) VALUES ('primary', 'zhou_mu@startup-coo.example.com', 'Primary', '#4285F4', 'Asia/Shanghai', 1, '2026-07-01T09:00:00+08:00');
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-exec-hold', 'primary', '周牧 — 陆家嘴 4F fit-out 项目规划 hold', '{"narrative": "Seed planning hold. Agent must create the operational fit-out plan and schedule the downstream Jingan filing / vendor / fit-up window / fire-acceptance / formaldehyde / handover events.", "meta": {"allowed_hours": null, "linked_rule_ids": [], "linked_standard_ids": [], "sch_template_id": null, "blocking_inspection_id": null}}', '陆家嘴金融中心 4F', '2026-07-01T15:00:00+08:00', '2026-07-01T15:30:00+08:00', 0, 'confirmed', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-jingan-filing-deadline', 'primary', '静安 装饰装修一件事 申请 ddl (SCH-001)', '{"narrative": "Jingan one-stop filing ddl. Must submit BIM, load-calc, fire-layout, vendor quals, safety plan before construction entry on D5 (2026-07-06).", "meta": {"allowed_hours": "weekday 09:00-17:00", "linked_rule_ids": ["rule_property_v3_005"], "linked_standard_ids": [], "sch_template_id": "SCH-001", "blocking_inspection_id": null, "application_id": "commercial_fit_up_filing_001"}}', 'Jingan one-stop online portal', '2026-07-02T09:00:00+08:00', '2026-07-04T18:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-fire-drawing-submit-ddl', 'primary', '消防 图纸 物业 初审 提交 ddl (SCH-002)', '{"narrative": "SCH-002 fire-drawing submission to property + Jingan platform. Must include BIM, load-calc >=4kW/100sqm, emergency-lighting layout (24 lamps, <=8m spacing), evacuation paths, smoke detectors, fire extinguishers.", "meta": {"allowed_hours": "weekday business", "linked_rule_ids": ["rule_property_v3_013"], "linked_standard_ids": [], "sch_template_id": "SCH-002", "blocking_inspection_id": null}}', '陆家嘴金融中心 物业办 + Jingan one-stop portal', '2026-07-05T09:30:00+08:00', '2026-07-05T17:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-fit-up-window-opens', 'primary', '物业 fit-up 期开始 (SCH-003) — 拆除可开工', '{"narrative": "SCH-003 fit-up window opens. Construction allowed only if Jingan filing approved, engineering-all-risk insurance certificate in force, fit-up deposit 30k paid, vendor qualification confirmed.", "meta": {"allowed_hours": "weekday 09:00-19:00", "linked_rule_ids": ["rule_property_v3_005", "rule_property_v3_013"], "linked_standard_ids": [], "sch_template_id": "SCH-003", "blocking_inspection_id": null, "application_id": "commercial_fit_up_filing_001"}}', '陆家嘴金融中心 4F', '2026-07-06T09:00:00+08:00', '2026-08-31T19:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-strong-weak-rough-in', 'primary', '强电 + 弱电 rough_in (SCH-007)', '{"narrative": "SCH-007 strong + weak electrical rough_in. Strong line >=4kW/100sqm * 300sqm = >=12kW. Weak: 30 network points + phone + 2 video-conference rooms + reception display. Emergency lighting conduit (24 lamps, <=8m spacing). UPS server closet on independent circuit.", "meta": {"allowed_hours": "weekday 09:00-19:00", "linked_rule_ids": ["rule_property_v3_013"], "linked_standard_ids": ["insp_std_003"], "sch_template_id": "SCH-007", "blocking_inspection_id": "electrical_acceptance"}}', '陆家嘴金融中心 4F', '2026-07-08T09:00:00+08:00', '2026-07-09T19:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-fire-inspection-onsite', 'primary', '消防 验收 现场 (SCH-013, insp_std_fire_acceptance)', '{"narrative": "SCH-013 fire-acceptance on-site inspection by 静安区 消防救援支队 验收科. Requirements: 24 emergency lamps (<=8m spacing), evacuation path width >=1.4m, smoke detector full coverage + interlock test, fire extinguisher placement, electrical load measured >=4kW/100sqm, formaldehyde retest <=0.05.", "meta": {"allowed_hours": "weekday 09:00-12:00", "linked_rule_ids": ["rule_property_v3_013"], "linked_standard_ids": ["insp_std_fire_acceptance"], "sch_template_id": "SCH-013", "blocking_inspection_id": "fire_inspection_app_001", "application_id": "fire_inspection_app_001"}}', '陆家嘴金融中心 4F', '2026-07-14T09:00:00+08:00', '2026-07-14T12:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT INTO attendees (event_id, email, name, response_status) VALUES ('fitout-seed-fire-inspection-onsite', 'contact@jingan-fire.gov.cn', NULL, 'tentative');
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-occupancy-d-day', 'primary', '入驻 D-day — 员工搬入 + 三方 handover (SCH-015)', '{"narrative": "SCH-015 occupancy D-day. Tenant lease starts charging on 09-01 regardless. All inspection gates must be approved, punch list closed or contractor-held, property fit-up deposit refund letter signed, formaldehyde retest <=0.05 mg/m^3 cleared.", "meta": {"allowed_hours": "business hours", "linked_rule_ids": [], "linked_standard_ids": ["insp_std_fire_acceptance", "insp_std_formaldehyde_commercial"], "sch_template_id": "SCH-015", "blocking_inspection_id": null}}', '陆家嘴金融中心 4F', '2026-09-01T09:00:00+08:00', '2026-09-01T12:00:00+08:00', 0, 'tentative', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', NULL, NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-property-noise-window', 'primary', '楼内 噪音 作业 窗口 09:00-19:00 (weekday, rule_lujiazui_001)', '{"narrative": "Recurring informational band: noise-generating work allowed only 09:00-19:00 weekday. 19:00 -> next 09:00 strict silence. Weekend requires 48h pre-approval from property. Statutory holidays blocked entirely.", "meta": {"allowed_hours": "weekday 09:00-19:00", "linked_rule_ids": ["rule_property_v3_005", "rule_property_v3_013"], "linked_standard_ids": [], "sch_template_id": null, "blocking_inspection_id": null}}', '陆家嘴金融中心 4F', '2026-07-06T09:00:00+08:00', '2026-07-06T19:00:00+08:00', 0, 'confirmed', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', '[''RRULE:FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR;UNTIL=20260901T190000Z'']', NULL);
INSERT OR REPLACE INTO events (event_id, calendar_id, summary, description, location, start_dt, end_dt, all_day, status, created_at, updated_at, recurrence_rule, parent_event_id) VALUES ('fitout-seed-weekend-restriction', 'primary', '周末施工 物业 管制 — 须 48h 报批 (rule_lujiazui_002)', '{"narrative": "Weekend (Sat/Sun) noise-generating work requires 48h pre-approval from property and may be denied. Low-noise finishing work (paint touch-up, soft-pack install) may proceed only with property notification.", "meta": {"allowed_hours": null, "linked_rule_ids": ["rule_property_v3_005"], "linked_standard_ids": [], "sch_template_id": null, "blocking_inspection_id": null}}', '陆家嘴金融中心 4F', '2026-07-11T00:00:00+08:00', '2026-07-12T23:59:00+08:00', 0, 'confirmed', '2026-07-01T09:00:00+08:00', '2026-07-01T09:00:00+08:00', '[''RRULE:FREQ=WEEKLY;BYDAY=SA,SU;UNTIL=20260901T235959Z'']', NULL);
